<script setup lang="ts">
import {ref,computed} from 'vue';import {useI18n} from 'vue-i18n';import {Mail,ArrowUpRight} from 'lucide-vue-next';import {CONTACT_EMAIL} from '../data/site';const {t,tm}=useI18n();const name=ref(''),email=ref(''),type=ref('0'),budget=ref('0'),message=ref('');const configured=computed(()=>!CONTACT_EMAIL.startsWith('REPLACE_'))
function send(){if(!configured.value){alert(t('contact.emailMissing'));return}const types=tm('contact.types') as string[],budgets=tm('contact.budgets') as string[];const subject=`[RYSEN Portfolio] ${types[Number(type.value)]} - ${name.value}`;const body=`Company / Name: ${name.value}\nReply email: ${email.value}\nProject: ${types[Number(type.value)]}\nBudget: ${budgets[Number(budget.value)]}\n\n${message.value}`;window.location.href=`mailto:${CONTACT_EMAIL}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`}
</script>
<template><section class="section bg-paper"><div class="wrap grid lg:grid-cols-[.9fr_1.1fr] gap-12 lg:gap-24"><div><p class="eyebrow mb-6">{{t('contact.eyebrow')}}</p><h1 class="section-title">{{t('contact.title')}}</h1><p class="muted leading-8 mt-6">{{t('contact.subtitle')}}</p><div class="mt-12 flex gap-3 items-center text-muted"><Mail :size="21"/><span>{{configured?CONTACT_EMAIL:'Email address to be configured'}}</span></div></div><form class="bg-white border border-[#e4e9f1] rounded-2xl p-6 md:p-10 shadow-sm space-y-6" @submit.prevent="send"><div><label for="name" class="font-bold text-sm block mb-2">{{t('contact.name')}}</label><input id="name" v-model="name" class="field" required maxlength="120"/></div><div><label for="email" class="font-bold text-sm block mb-2">{{t('contact.email')}}</label><input id="email" v-model="email" type="email" class="field" required maxlength="180"/></div><div class="grid sm:grid-cols-2 gap-5"><div><label for="type" class="font-bold text-sm block mb-2">{{t('contact.type')}}</label><select id="type" v-model="type" class="field"><option v-for="(item,i) in (tm('contact.types') as string[])" :key="i" :value="String(i)">{{item}}</option></select></div><div><label for="budget" class="font-bold text-sm block mb-2">{{t('contact.budget')}}</label><select id="budget" v-model="budget" class="field"><option v-for="(item,i) in (tm('contact.budgets') as string[])" :key="i" :value="String(i)">{{item}}</option></select></div></div><div><label for="message" class="font-bold text-sm block mb-2">{{t('contact.message')}}</label><textarea id="message" v-model="message" class="field min-h-[155px]" required maxlength="4000"></textarea></div><button type="submit" class="btn btn-primary w-full">{{t('contact.send')}} <ArrowUpRight :size="18"/></button><p class="text-xs text-muted leading-6">{{t('contact.note')}}</p></form></div></section></template>
